import sys
sys.path.insert(0, '.')
from src.flatten import flatten


def test_flat_list():
    assert flatten([1, 2, 3]) == [1, 2, 3]


def test_nested():
    assert flatten([1, [2, 3], [4, [5, 6]]]) == [1, 2, 3, 4, 5, 6]


def test_deeply_nested():
    assert flatten([[[1]], [[2, 3]]]) == [1, 2, 3]


def test_empty():
    assert flatten([]) == []


def test_mixed_depth():
    assert flatten([1, [], [2, [3, [4]]]]) == [1, 2, 3, 4]
